using System;
using System.IO;
using System.Linq;
namespace JingFamily {
 public static class PurgeTests {
  public static int Run(string dir){int count=0;Action<bool,string> check=(ok,label)=>{if(!ok)throw new Exception("Purge test: "+label);count++;};Action<Action,string> reject=(a,label)=>{bool thrown=false;try{a();}catch{thrown=true;}check(thrown,label);};string oldBase=Library.BaseRoot;string root=Path.Combine(dir,"purge-library");Library.Initialize(root);string activeId=Library.Index.ActiveId;string safeFile=Path.Combine(Store.Root,"media","keep.txt");File.WriteAllText(safeFile,"must survive");var victim=Library.CreateData(Store.Sample(),"删除验证家谱");Library.Open(victim.Id);string media=Store.AddMedia(safeFile);Store.Data.Documents.Add(new Document{Title="删除验证资料",File=media});Store.Save();Library.Open(activeId);Library.Remove(victim.Id);var item=Library.Index.Trash.Single();string victimRoot=Library.Child("trash",item.TrashId);check(File.Exists(Path.Combine(victimRoot,media)),"trash contains attachment");reject(()=>Library.PermanentlyDelete(item.TrashId,"错误名称"),"wrong name refused");check(File.Exists(Path.Combine(victimRoot,"family.xml"))&&!item.Purging,"wrong name changes nothing");reject(()=>Library.PermanentlyDelete(activeId,"我的家谱"),"active family cannot be purged");
   string lockFile=Path.Combine(victimRoot,"locked.txt");File.WriteAllText(lockFile,"locked");using(var stream=new FileStream(lockFile,FileMode.Open,FileAccess.ReadWrite,FileShare.None)){bool errorContext=false;try{Library.PermanentlyDelete(item.TrashId,item.Entry.Name);}catch(Exception ex){errorContext=ex.Message.Contains("永久删除未全部完成");}check(errorContext,"locked file keeps incomplete purge context");check(item.Purging,"locked operation enters deletion state");check(item.Purging,"failed deletion marked");reject(()=>Library.Restore(item.TrashId),"partial deleted family cannot restore");}Library.PermanentlyDelete(item.TrashId,item.Entry.Name);check(!Directory.Exists(victimRoot)&&Library.Index.Trash.Count==0,"retry deletes files and metadata");check(File.ReadAllText(safeFile)=="must survive"&&Library.Index.ActiveId==activeId,"active files unaffected");reject(()=>Library.Restore(item.TrashId),"permanent delete cannot restore");
   var malicious=new RemovedFamily{Entry=new FamilyEntry{Id=Guid.NewGuid().ToString("N"),Name="非法路径"},TrashId="../families"};Library.Index.Trash.Add(malicious);reject(()=>Library.PermanentlyDelete(malicious.TrashId,malicious.Entry.Name),"invalid trash path refused");Library.Index.Trash.Remove(malicious);check(File.Exists(safeFile),"path guard preserves sibling family");
   for(int i=0;i<2;i++){var entry=Library.Create("批量删除验证"+i);Library.Remove(entry.Id);}reject(()=>Library.EmptyTrash("清空"),"bulk phrase required");check(Library.Index.Trash.Count==2,"bad phrase preserves all");var readonlyEntry=Library.Index.Trash[0];string readonlyFile=Path.Combine(Library.Child("trash",readonlyEntry.TrashId),"family.xml");File.SetAttributes(readonlyFile,File.GetAttributes(readonlyFile)|FileAttributes.ReadOnly);Library.EmptyTrash("永久清空回收区");check(Library.Index.Trash.Count==0&&File.Exists(safeFile),"bulk purge only removes trash");
   var missing=new RemovedFamily{Entry=new FamilyEntry{Id=Guid.NewGuid().ToString("N"),Name="中断后的空目录记录"},TrashId=Guid.NewGuid().ToString("N"),Purging=true};Library.Index.Trash.Add(missing);Library.PermanentlyDelete(missing.TrashId,missing.Entry.Name);check(!Library.Index.Trash.Contains(missing),"missing directory can finalize deletion");Library.Initialize(root);check(Library.Index.Trash.Count==0&&Library.Index.Families.Count==1,"purge state persists after restart");
   check(!PurgeConfirmation.Matches("家谱 ","家谱")&&!PurgeConfirmation.Matches("",""),"confirmation strict and nonempty");using(var dialog=new PurgeConfirmation("家谱",false,1)){check(!dialog.ConfirmButton.Enabled,"danger button initially disabled");dialog.NameInput.Text="其他";check(!dialog.ConfirmButton.Enabled,"mismatch keeps disabled");dialog.NameInput.Text="家谱";check(dialog.ConfirmButton.Enabled,"exact name enables delete");check(dialog.CancelButton!=null&&dialog.AcceptButton==null,"no enter-to-delete shortcut");}using(var dialog=new PurgeConfirmation("",true,3)){dialog.NameInput.Text="永久清空回收区";check(dialog.ConfirmButton.Enabled,"bulk phrase enables clear");}Library.Initialize(oldBase);Library.Index.Version=1;using(var f=File.Create(Library.IndexPath))new System.Xml.Serialization.XmlSerializer(typeof(FamilyIndex)).Serialize(f,Library.Index);Library.Initialize(oldBase);check(Library.Index.Version==2,"previous library catalog migrates safely");return count;
  }
 }
}
